namespace monstres {

// Every mesh the game draws, in drawing order (opaque meshes first, then the
// transparent ones in this order). Most are model files in assets/models/
// (generated by tools/make_models.py, see that script for sizes and
// conventions); Ground, Path, Water and the continent's meshes depend on the
// world and are built at runtime (see terrain_mesh.hpp and far_terrain.hpp).
enum class MeshId : size_t {
  Cube,
  Crate,
  Tree,
  Pine,
  Rock0, Rock1, Rock2, Rock3,
  Log,
  Stump,
  Bush,
  GrassShort,
  GrassTall,
  Flower,
  Cloud0, Cloud1, Cloud2,
  CloudLow0, CloudLow1, CloudLow2,  // the same, from afar
  Mountain0, Mountain1,
  // Character parts (see src/render/characters.cpp).
  Eye,
  PlayerLeg, PlayerTorso, PlayerArm, PlayerHead, PlayerStaff, PlayerCrystal,
  // The magician's look (characters.cpp, wizard_look): white parts are tinted.
  PlayerTorsoWoman, PlayerTrims, PlayerTrimsWoman, PlayerNeck, PlayerCuff, PlayerHeadWoman,
  PlayerHairShort, PlayerHairLong, PlayerHairBun,
  PlayerHairShortHat, PlayerHairLongHat, PlayerHairBunHat, PlayerHairShortHood, PlayerHairLongHood,  // fitting under them
  PlayerBeard, PlayerHat, PlayerHatBand, PlayerHood, PlayerWand,
  CompanionBody, CompanionLeg, CompanionHead, CompanionEar, CompanionTail,
  SlimeBody,
  MushroomStem, MushroomCap, MushroomLeg,
  BirdBody, BirdWing, BirdLeg,
  SparkBody, SparkQuills, SparkQuillsLong, SparkHead, SparkEar, SparkTail, SparkLeg,
  AxolotlBody, AxolotlHead, AxolotlGills, AxolotlTail, AxolotlLeg,
  CristiBody, CristiEar, CristiLeg, CristiCrystal, CristiShards,
  RaccoonBody, RaccoonHead, RaccoonEar, RaccoonTail, RaccoonLeg,
  OwlBody, OwlWing, OwlLeg, OwlTufts,
  SheepBody, SheepHead, SheepEar, SheepTail, SheepLeg, SheepHorns,
  MoleBody, MoleHead, MoleEar, MoleTail, MoleLeg, MoleStar,
  // The north's (north.hpp): Caillou, Cabri, Givri.
  GolemBody, GolemHead, GolemEar, GolemTail, GolemLeg, GolemMoss,
  GoatBody, GoatHead, GoatEar, GoatTail, GoatLeg, GoatHorns, GoatHornsSpiral, GoatBeard,
  ErmineBody, ErmineHead, ErmineEar, ErmineTail, ErmineLeg, ErmineFrost,
  // Village.
  HouseCottage, HouseChimney, HouseHut, Fence, Sign, Well, Barrel, Lamp,
  VillagerTorso, VillagerLeg, VillagerArm, VillagerHand, VillagerHead,
  HairShort, HairLong, HairBun, HatCap, HatStraw, HatBeanie,
  CrowBody, CrowWing, CrowLeg,
  FishBody, FishTail, FishFin,
  EyeIris, Horn, Bulb,  // variants of the monsters (tinted by the game)
  // Ruins of the tower.
  Tower, RuinWallLow, RuinWallHigh, Pillar, FallenPillar, Rubble, RuneStone,
  // The castle and the cave.
  CastleWall, CastleTower, CastleGate, CastleKeep, CaveMouth, Crystal, Teleporter,
  // Inside (interior.hpp): furniture, the tower's stair and trapdoor.
  Table, Chair, Bed, Shelf, Hearth, HearthFire, Rug, Step, Hatch,
  // The west (west.hpp).
  Cart, CartUp, Goods, Bridge, Farmhouse, Barn, FruitTree, CropsWheat, CropsCabbage, Haystack, Windmill, WindmillSails,
  WaterMill, MillWheel,
  Cabin, Tent, Campfire, CampfireFire, Woodpile, HollowTree, Burrow, Lighthouse, LighthouseLamp, Menhir, Meteorite,
  // The north (north.hpp).
  Chalet, MineEntrance, Minecart, MinecartLoaded, Larch, StoneWall, Cairn, HotSpring, MineProp,
  // Rochebrune and along the roads (north.hpp, roads.hpp).
  Arena, Grotto, Shrine, Bench, Stall,
  // The sites (sites.hpp).
  Pier, Boat0, Boat1, Boat2, Boat3, FishRack, NetRack, AbbeyWall, AbbeyGate, Temple, Belfry, Dorter, Refectory,
  Gravestone0, Gravestone1, Cross, Chapel, Crane, Block, Beehive, Dolmen, Wreck, Aqueduct,
  // Seen from afar (simplified), and at a middle distance.
  TreeFar, PineFar, TreeMid, BushFar, LarchFar,
  GrassShortFar, GrassTallFar, FlowerFar,
  // The seasons: the tree in winter (near; at a middle distance and afar),
  // fallen leaves on the ground, leaves blown around the camera (weather_view.hpp).
  TreeBare, TreeBareFar, LeafLitter, Leaves,
  IconQuestion, IconExclaim, IconPlus, IconCross,  // over villagers (npc_marks)
  IconBolt, IconCoin, IconFarm,  // over aggressive monsters; the merchant, the farm (npc_marks)
  Ground,  // built at runtime
  InteriorShell,  // inside: floor, walls and ceiling, built at runtime (interior_mesh.hpp)
  FarGround, Lava,  // the continent (far pass), built at runtime
  // Transparent, drawn last, in this order:
  Path,    // built at runtime
  Water,   // built at runtime
  FarWater,  // the continent's ocean and lakes (far pass), built at runtime
  Shadow,  // after the path so shadows fall on it
  Ripple,
  Smoke,
  Sparkle,
  Gust,        // an air monster's throw: swirling wind
  DoorGlow,    // the light in a door's opening, when the player comes near
  RuneCircle,  // the capture seal
  FallsBand,   // a band of a waterfall (stacked, each fading as it goes down)
  RainShaft, Bolt,  // the weather (far pass)
  Rain, Snow,       // around the camera
  Count
};
inline constexpr size_t kMeshCount = static_cast<size_t>(MeshId::Count);
inline constexpr size_t kRockVariants = 4;
inline constexpr size_t kCloudVariants = 3;
inline constexpr size_t kMountainVariants = 2;

// What a mesh is, for the frame statistics (RenderStats::triangles_by_group).
enum class MeshGroup : uint8_t { Terrain, Vegetation, Scenery, Characters, Effects, Sky };
inline MeshGroup mesh_group(MeshId id) {
  switch (id) {
    case MeshId::Ground: case MeshId::Path: case MeshId::Water: case MeshId::FarGround: case MeshId::FarWater:
    case MeshId::Lava: case MeshId::InteriorShell:
      return MeshGroup::Terrain;
    case MeshId::GrassShort: case MeshId::GrassTall: case MeshId::Flower:
    case MeshId::GrassShortFar: case MeshId::GrassTallFar: case MeshId::FlowerFar: case MeshId::LeafLitter:
      return MeshGroup::Vegetation;
    case MeshId::Cloud0: case MeshId::Cloud1: case MeshId::Cloud2: case MeshId::Mountain0: case MeshId::Mountain1:
    case MeshId::CloudLow0: case MeshId::CloudLow1: case MeshId::CloudLow2: case MeshId::RainShaft: case MeshId::Bolt:
      return MeshGroup::Sky;
    case MeshId::Shadow: case MeshId::Ripple: case MeshId::Smoke: case MeshId::Sparkle: case MeshId::RuneCircle:
    case MeshId::DoorGlow: case MeshId::Gust: case MeshId::FallsBand:
    case MeshId::Rain: case MeshId::Snow: case MeshId::Leaves:
      return MeshGroup::Effects;
    default: break;
  }
  const auto i = static_cast<size_t>(id);
  if (i >= static_cast<size_t>(MeshId::Eye) && i <= static_cast<size_t>(MeshId::ErmineFrost)) return MeshGroup::Characters;
  if (i >= static_cast<size_t>(MeshId::VillagerTorso) && i <= static_cast<size_t>(MeshId::Bulb)) return MeshGroup::Characters;
  return MeshGroup::Scenery;
}

inline MeshId mesh_offset(MeshId first, size_t i) {
  return static_cast<MeshId>(static_cast<size_t>(first) + i);
}

// File name (without .glb) of a model, or nullptr for runtime meshes.
const char* model_name(MeshId id);

// Loads a glTF binary file (.glb): every triangle primitive of every node,
// with node transforms applied. Missing normals are computed (flat), missing
// colors are white. Returns nullopt and fills `error` on failure.
std::optional<MeshData> load_model(const std::string& path, std::string* error = nullptr);

// Loads every model file of `dir`. The result is indexed by MeshId; runtime
// meshes are left empty. Returns false and fills `error` if a file fails.
bool load_models(const std::string& dir, std::vector<MeshData>& meshes, std::string* error = nullptr);

}  // namespace monstres
